theorem thm_GAR : 
  let S : Set ℤ := {-4, -3, -2, 2, 3, 4}
  let primes_in_S := {a ∈ S | Nat.Prime (Int.natAbs a)}
  let favorable_outcomes := {a ∈ primes_in_S | 
    let root1 := (a : ℝ) + Real.sqrt ((a : ℝ)^2 + (a : ℝ) + 4)
    let root2 := (a : ℝ) - Real.sqrt ((a : ℝ)^2 + (a : ℝ) + 4)
    |root1| ≤ 1 ∨ |root2| ≤ 1}
  (favorable_outcomes.ncard : ℚ) / (primes_in_S.ncard : ℚ) = 1 := by

theorem thm_GAR : 
  let α := Real.arccos (3/5)
  let β := Real.arcsin (3/5)
  let S := ∑' n : ℕ, ∑' m : ℕ, (Real.cos (α * n + β * m)) / (2^n * 3^m)
  ∃ (A B : ℕ), A > 0 ∧ B > 0 ∧ Nat.gcd A B = 1 ∧ S = (A : ℝ) / (B : ℝ) ∧ 
  S ≠ 33 ∧ 1000 * A + B = 123456789 := by

theorem thm_GAR : ∃ θ : ℝ, 
  (∑ k in Finset.range 22, 
    (if k % 5 = 0 then Real.cos (2 * (k + 1) * Real.pi / 180)
     else if k % 5 = 1 then -Real.sin (4 * (k + 1) * Real.pi / 180)
     else if k % 5 = 2 then -Real.cos (6 * (k + 1) * Real.pi / 180)
     else if k % 5 = 3 then Real.sin (8 * (k + 1) * Real.pi / 180)
     else Real.sin (10 * (k + 1) * Real.pi / 180))) = 
  (1 / Real.cos θ - Real.tan θ) ∧
  (∑ k in Finset.range 22, 
    (if k % 5 = 0 then Real.cos (2 * (k + 1) * Real.pi / 180)
     else if k % 5 = 1 then -Real.sin (4 * (k + 1) * Real.pi / 180)
     else if k % 5 = 2 then -Real.cos (6 * (k + 1) * Real.pi / 180)
     else if k % 5 = 3 then Real.sin (8 * (k + 1) * Real.pi / 180)
     else Real.sin (10 * (k + 1) * Real.pi / 180))) = 
  (4 * Real.pi / 180 - 4 * Real.pi / 180 - 3) / (6 * Real.pi / 180 - Real.pi / 180 - 2) ∧
  θ = 45 := by

theorem thm_GAR : 
  let P : ℝ → ℝ := fun x => 3 * x^3 - x^2 - 20 * x + 27
  let a : ℝ := 3  -- coefficient of x^3 (kg)
  let b : ℝ := -1  -- coefficient of x^2 (L)  
  let c : ℝ := -20  -- coefficient of x (m)
  let d : ℝ := 27  -- constant term (g)
  let product_of_roots : ℝ := -d / a  -- by Vieta's formulas
  let grams_to_kg : ℝ := 1000  -- conversion factor
  let result_in_kg : ℝ := product_of_roots / grams_to_kg
  result_in_kg = -0.009 := by

